import re
from typing import List, Tuple


class ExpressionParser:
    """
    A recursive descent parser for mathematical expressions.

    Supports:
    - Integer and floating point numbers
    - Unary minus (negative numbers)
    - Binary operators: +, -, *, /
    - Parentheses
    - Operator precedence: parentheses > *, / > +, -

    Raises ZeroDivisionError when dividing by zero.
    """

    def __init__(self, expr: str):
        # Remove all whitespace
        self.expr = expr.replace(' ', '')
        self.pos = 0

    def parse(self) -> float:
        result = self.parse_expression()
        if self.pos != len(self.expr):
            raise ValueError(f"Unexpected character at position {self.pos}: '{self.expr[self.pos]}'")
        # Return int if the result is an integer, otherwise float
        if isinstance(result, float) and result.is_integer():
            return int(result)
        return result

    def parse_expression(self) -> float:
        """Parse addition and subtraction (left-associative)."""
        left = self.parse_term()
        while self.pos < len(self.expr) and self.expr[self.pos] in ('+', '-'):
            op = self.expr[self.pos]
            self.pos += 1
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term(self) -> float:
        """Parse multiplication and division (left-associative)."""
        left = self.parse_factor()
        while self.pos < len(self.expr) and self.expr[self.pos] in ('*', '/'):
            op = self.expr[self.pos]
            self.pos += 1
            right = self.parse_factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right
        return left

    def parse_factor(self) -> float:
        """Parse unary operators (negative sign) and primary expressions."""
        if self.pos < len(self.expr) and self.expr[self.pos] == '-':
            self.pos += 1
            return -self.parse_factor()
        if self.pos < len(self.expr) and self.expr[self.pos] == '+':
            self.pos += 1
            return self.parse_factor()
        return self.parse_primary()

    def parse_primary(self) -> float:
        """Parse numbers or parenthesized expressions."""
        if self.pos >= len(self.expr):
            raise ValueError("Unexpected end of expression")

        if self.expr[self.pos] == '(':
            self.pos += 1  # Skip '('
            result = self.parse_expression()
            if self.pos >= len(self.expr) or self.expr[self.pos] != ')':
                raise ValueError("Expected closing parenthesis")
            self.pos += 1  # Skip ')'
            return result

        # Parse a number (integer or float)
        start = self.pos
        while self.pos < len(self.expr) and (self.expr[self.pos].isdigit() or self.expr[self.pos] == '.'):
            self.pos += 1

        if self.pos == start:
            raise ValueError(f"Expected a number at position {self.pos}")

        num_str = self.expr[start:self.pos]
        if '.' in num_str:
            return float(num_str)
        else:
            return int(num_str)


def eval_expression(expr: str) -> Union[int, float]:
    """
    Evaluate a mathematical expression with proper operator precedence.

    Args:
        expr: A string containing a mathematical expression.
              Supports +, -, *, /, parentheses, and unary minus.

    Returns:
        The result of the expression as an int or float.

    Raises:
        ZeroDivisionError: If the expression involves division by zero.
        ValueError: If the expression is malformed.
    """
    if not isinstance(expr, str):
        raise TypeError("Expression must be a string")

    if not expr.strip():
        raise ValueError("Expression cannot be empty")

    parser = ExpressionParser(expr)
    result = parser.parse()
    return result
